runtime.codigo:
import { BrandThemeProvider, useBrandTheme } from "@/lib/brand-theme"

function TrocaDeMarca() {
  const { brands, active, setBrand } = useBrandTheme()
  return brands.map((b) => (
    <button key={b.slug} aria-pressed={active?.slug === b.slug} onClick={() => setBrand(b.slug)}>
      {b.name}
    </button>
  ))
}

export default function App() {
  return (
    <BrandThemeProvider defaultBrand="norte-verde">
      <TrocaDeMarca />
    </BrandThemeProvider>
  )
}

exemplos.use-knob-drag:
import { useKnobDrag } from "@/hooks/use-knob-drag"

export function Ganho() {
  const { currentValue, rotation, handleMouseDown, handleKeyDown } = useKnobDrag({ min: 0, max: 10, value: 5 })
  return (
    <div role="slider" tabIndex={0} aria-valuenow={currentValue} onMouseDown={handleMouseDown} onKeyDown={handleKeyDown} style={{ rotate: `${rotation}deg` }} />
  )
}

