exemplos.tempo-clock:
import { createTempoClock } from "@/lib/tempo-clock"

const relogio = createTempoClock({ bpm: 120, div: 2 })

function quadro(agora: number) {
  const { beat, env } = relogio.tick(agora)
  document.body.style.opacity = String(beat ? 1 : env)
  requestAnimationFrame(quadro)
}

requestAnimationFrame(quadro)

